internal sealed class StateApproximationS3QuantumAlgebraStateApproximationPhysicslib4GNSExtremeStateDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Purity and whole-state-space extremality", H("Purity and whole-state-space extremality"), Blocks(
        Paragraph(Text("A state is pure when every positive functional dominated by it is a scalar multiple of it. This is equivalent to extremality in the entire convex state space. For positive continuous functionals, the operator norm is the real value at the unit; normalization then gives omega(1)=1. Restriction or a chosen family of states is not substituted for the whole state space.")),
        Describe.Lean(DescribeId.Create("statement0"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/Physicslib4/GNS/ExtremeState.norm_eq_re_apply_one_of_positive"),
            H("norm_eq_re_apply_one_of_positive"), StatementSource.FromAuthor(Disp(Statement0())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Apply cauchy_schwarz_inequality with first argument 1, then use CStarRing.norm_star_mul_self and the operator norm bound to obtain norm(phi(b)) squared at most Re(phi(1)) times norm(phi) times norm(b) squared. The induced operator norm estimate and nonnegativity imply norm(phi) at most Re(phi(1)), treating norm(phi)=0 separately. Evaluating at 1, whose norm is 1 in a nontrivial C*-algebra, gives the reverse inequality."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement1"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/Physicslib4/GNS/ExtremeState.apply_one"),
            H("apply_one"), StatementSource.FromAuthor(Disp(Statement1())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The helper nontrivial_of_state excludes the zero algebra using the normalized operator norm. Then norm_eq_re_apply_one_of_positive identifies the real part of omega(1) with 1, while positivity at 1 forces its imaginary part to vanish. Complex extensionality gives the value 1."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement2"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/Physicslib4/GNS/ExtremeState.isExtremePoint_of_isPure"),
            H("isExtremePoint_of_isPure"), StatementSource.FromAuthor(Disp(Statement2())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For a decomposition with 0<t<1, the positive functional psi=t omega1 is dominated by omega because the remaining term (1-t) omega2 is positive. Purity makes psi a scalar multiple of omega; State.apply_one fixes that scalar to t. Cancellation first identifies omega1 with omega, and then the decomposition identifies omega2 with omega."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement3"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/Physicslib4/GNS/ExtremeState.isPure_of_isExtremePoint"),
            H("isPure_of_isExtremePoint"), StatementSource.FromAuthor(Disp(Statement3())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For a dominated positive psi, norm_eq_re_apply_one_of_positive gives lambda=Re(psi(1))=norm(psi) in [0,1]. If lambda=0 then psi=0; if lambda=1 the positive complement omega-psi has norm zero. Otherwise normalize psi and omega-psi by lambda and 1-lambda to obtain two states in a genuine convex decomposition of omega; extremality equates these states and yields psi=lambda omega."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement4"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/Physicslib4/GNS/ExtremeState.isPure_iff_isExtremePoint"),
            H("isPure_iff_isExtremePoint"), StatementSource.FromAuthor(Disp(Statement4())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The two implications are isExtremePoint_of_isPure and isPure_of_isExtremePoint. Their conjunction identifies the order-theoretic domination definition of purity with the pointwise convex-decomposition definition of extremality; no new characterization of representations is required here."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement5"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/Physicslib4/GNS/ExtremeState.toContinuousLinearMap_injective"),
            H("toContinuousLinearMap_injective"), StatementSource.FromAuthor(Disp(Statement5())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("A State consists of its continuous linear functional and proofs of positivity and normalization. Equality of the functional therefore determines equality of states, since the remaining fields are propositions; State.mk.injEq implements this extensionality."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement6"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/Physicslib4/GNS/ExtremeState.mem_extremePoints_iff_isExtremePoint"),
            H("mem_extremePoints_iff_isExtremePoint"), StatementSource.FromAuthor(Disp(Statement6())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Translate a pointwise convex decomposition into membership of an openSegment in the real vector space of continuous linear functionals. In the forward direction, Mathlib's mem_extremePoints equates the endpoint functionals and State.toContinuousLinearMap_injective equates their states. Conversely write the positive segment coefficients as t and 1-t, apply State.IsExtremePoint, and use their sum being 1 to identify both endpoints with omega."))), DescribeRole.Theorem))));

